package com.cdac.cssip.meeting.dto;import jakarta.validation.constraints.*;import java.time.*;import java.util.*;public final class MeetingDtos{private MeetingDtos(){}public record CreateMeetingRequest(@NotNull Long branchId,@NotBlank @Size(max=160)String title,@Size(max=1200)String agenda,@NotBlank String platform,@NotBlank String meetingLink,@NotNull @Future LocalDateTime scheduledAt,@NotNull @Min(15) @Max(240)Integer durationMinutes,@NotEmpty List<Long> studentIds){}public record UpdateMeetingRequest(@NotBlank @Size(max=160)String title,@Size(max=1200)String agenda,@NotBlank String platform,@NotBlank String meetingLink,@NotNull @Future LocalDateTime scheduledAt,@NotNull @Min(15) @Max(240)Integer durationMinutes){}public record CancelRequest(@Size(max=500)String reason){}public record MeetingView(Long id,Long staffId,Long branchId,String title,String agenda,String platform,String meetingLink,LocalDateTime scheduledAt,Integer durationMinutes,String status,String cancellationReason,LocalDateTime createdAt,List<Long> studentIds){} }
